target.css:
:root {
  --paper: #fffdf5;
  --ink: #24333c;
  --muted: #718088;
  --line: #dce2d8;
  --sun: #f4b73f;
  --sun-deep: #d88924;
  --sun-pale: #fff1c9;
  --mint: #357c70;
  --mint-pale: #e2f1e9;
  --sky: #dceef0;
  --alert: #bd5a42;
}

* {
  box-sizing: border-box;
}

.oven-card {
  width: 492px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 64px;
  padding: 11px 16px;
  border-bottom: 1px solid var(--line);
}

.solar-mark {
  display: grid;
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  place-items: center;
  border-radius: 12px;
  background: var(--sun-pale);
  color: var(--sun-deep);
  font-size: 22px;
  line-height: 1;
}

.title-block {
  min-width: 0;
  flex: 1;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  line-height: 1.1;
}

h1 {
  margin: 0;
  font-size: 18px;
  font-weight: 750;
  letter-spacing: -0.3px;
  line-height: 1.2;
}

.run-chip {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--mint-pale);
  color: var(--mint);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.7px;
}

.thermal-grid {
  display: grid;
  grid-template-columns: 150px 1fr;
  gap: 14px;
  padding: 14px 16px;
}

.heat-orbit {
  display: flex;
  min-height: 154px;
  margin: 0;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border: 1px dashed var(--sun-deep);
  border-radius: 16px;
  background: var(--sun-pale);
}

.sun-core {
  display: grid;
  width: 82px;
  height: 82px;
  place-items: center;
  border: 7px solid var(--sun);
  border-radius: 50%;
  background: var(--paper);
  color: var(--sun-deep);
  font-size: 21px;
  font-weight: 800;
  letter-spacing: -1px;
}

figcaption {
  margin-top: 7px;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.25;
  text-align: center;
}

figcaption strong {
  color: var(--ink);
  font-weight: 750;
}

.readings {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 7px;
}

.measure {
  display: flex;
  min-width: 0;
  padding: 9px 7px 7px;
  flex-direction: column;
  justify-content: space-between;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--paper);
}

.amber-measure {
  border-color: var(--sun);
}

.measure-label {
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
  line-height: 1.1;
}

.measure strong {
  margin-top: 5px;
  color: var(--ink);
  font-size: 15px;
  line-height: 1;
  white-space: nowrap;
}

.measure small {
  margin-top: 5px;
  color: var(--muted);
  font-size: 9px;
  line-height: 1;
}

.spectrum {
  display: flex;
  grid-column: 1 / -1;
  align-items: end;
  gap: 5px;
  padding: 8px 9px;
  border-radius: 10px;
  background: var(--sky);
}

.spectrum-label {
  margin-right: auto;
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
}

.bar {
  display: block;
  width: 7px;
  border-radius: 5px;
  background: var(--sun);
}

.bar-one { height: 8px; }
.bar-two { height: 13px; }
.bar-three { height: 18px; }
.bar-four { height: 24px; background: var(--sun-deep); }

.spectrum-value {
  margin-left: 2px;
  color: var(--ink);
  font-size: 11px;
  font-weight: 800;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  border-top: 1px solid var(--line);
  background: var(--paper);
}

.conditions {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.2;
}

.condition-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--mint);
}

button {
  border: 0;
  border-radius: 8px;
  padding: 8px 11px;
  background: var(--ink);
  color: var(--paper);
  font-size: 11px;
  font-weight: 750;
  line-height: 1;
}

